import{_ as t,H as n,f as o,b as e,j as i}from"./chunks/framework.CGh9YNlq.js";const m=JSON.parse('{"title":"LangChain","description":"","frontmatter":{},"headers":[],"relativePath":"notes/LangChain.md","filePath":"notes/LangChain.md"}'),s={name:"notes/LangChain.md"};function r(h,a,l,c,p,d){return n(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"langchain",tabindex:"-1"},[i("LangChain "),e("a",{class:"header-anchor",href:"#langchain","aria-label":'Permalink to "LangChain"'},"​")],-1),e("p",null,"LangChain builds on the idea stressed in the preceding section: that prompting techniques are most useful when used together. To make that easier, LangChain provides simple abstractions for each major promting technique. By abstraction we mean Python and JavaScript functions and classes that encapsulate the ideas of those techniques into easy-to use wrappers. These abstractions are designed to play well together and to be combined into a larger LLM application.",-1),e("p",null,"LangChain provides integrations with the major LLM providers, both commercial (OpenAI, Anthropic, Google) and open source(LIama, Gemma, and others).",-1),e("p",null,"LangChain also provides prompt template abstractions, which enable you to reuse prompts more than once, separating static text in the prompt from placeholders that will be different for each time you send it to the LLM to get a completion generated.",-1),e("p",null,"LangChain contains many integrations with third-party services(Such as Google Sheets...) exposed as tools, which is a standard interface for functions to be used in the tool-calling technique.",-1),e("p",null,"For RAG, LangChain provides integrations with the major embedding models(language models designed to output a numeric representation, the embedding, of the meaning of a sentence, paragraph, and so on),vector stores (databases dedicated to storing embeddings), and vector indexes (regular databases with vector-storing capabilities).",-1),e("p",null,"For CoT, LangChain (through the LangGraph library) provides agent abstractions that combine chain-of-thought reasoning and tool calling, first popularized by the ReAct paper. This enables building LLM applications that do the following:",-1),e("p",null,"1.Reason about the steps to take. 2.Translate those steps into externnal tool calls. 3.Receive the output of those tool calls. 4.Repeat until the task is accomplished.",-1)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
